{
  "name": "OBP USB通信组件",
  "name_en": "OBP USB Communication Interface",
  "manufacturer": "",
  "description": "这是一个非物理的USB通信组件，用于海洋光学系列光谱仪的OBP协议通信。它负责打开和关闭USB连接、发送命令、发起与接收查询，以及按不同读取模式获取USB数据，供实验软件与光谱仪进行底层数据交换。",
  "description_en": "This is a non-physical USB communication component for OBP-based communication with Ocean Optics spectrometers. It handles opening and closing the USB connection, sending commands, initiating and receiving queries, and reading USB data through different transfer modes so that experiment software can exchange low-level data with the spectrometer.",
  "actions": [
    {
      "action_name": "auto-send_command",
      "description": "向USB设备发送一条OBP命令消息。",
      "description_en": "Send an OBP command message to the USB device."
    },
    {
      "action_name": "auto-innitiate_query",
      "description": "发起一次OBP查询，但暂不接收回复。",
      "description_en": "Initiate an OBP query without receiving the reply yet."
    },
    {
      "action_name": "auto-receive_query",
      "description": "接收先前发起的OBP查询回复。",
      "description_en": "Receive the reply for a previously initiated OBP query."
    },
    {
      "action_name": "auto-query",
      "description": "执行一次完整的OBP查询并获取回复。",
      "description_en": "Perform a complete OBP query and obtain the reply."
    },
    {
      "action_name": "auto-open_device",
      "description": "打开USB设备连接。",
      "description_en": "Open the USB device connection."
    },
    {
      "action_name": "auto-is_open",
      "description": "检查USB设备连接是否已打开。",
      "description_en": "Check whether the USB device connection is open."
    },
    {
      "action_name": "auto-close_device",
      "description": "关闭USB设备连接。",
      "description_en": "Close the USB device connection."
    },
    {
      "action_name": "auto-usb_send",
      "description": "通过USB发送原始数据。",
      "description_en": "Send raw data over USB."
    },
    {
      "action_name": "auto-usb_read_lowspeed",
      "description": "以低速方式从USB读取数据。",
      "description_en": "Read data from USB using the low-speed mode."
    },
    {
      "action_name": "auto-usb_read_highspeed",
      "description": "以高速方式从USB读取数据。",
      "description_en": "Read data from USB using the high-speed mode."
    },
    {
      "action_name": "auto-usb_read_highspeed_alt",
      "description": "以备用高速方式从USB读取数据。",
      "description_en": "Read data from USB using the alternate high-speed mode."
    },
    {
      "action_name": "auto-set_default_read",
      "description": "设置默认的USB读取方式。",
      "description_en": "Set the default USB read mode."
    }
  ],
  "tag_hints": [
    "USB communication",
    "Ocean Binary Protocol",
    "spectrometer interface",
    "message transport",
    "USB read modes",
    "Ocean Optics"
  ]
}

